"use client";

import { Eraser, Sparkles } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { MAX_CHARS } from "@/components/tts-provider";

const SAMPLE_TEXT =
  "Hello! Welcome to FreeTTS. Everything you hear is generated by artificial intelligence running entirely on your device — no servers, no accounts, no fees. Try changing the voice, or adjusting the speaking speed.";

export function TextEditor({
  text,
  onChange,
  disabled,
}: {
  text: string;
  onChange: (t: string) => void;
  disabled?: boolean;
}) {
  const count = text.length;
  const over = count > MAX_CHARS;

  return (
    <div className="space-y-2">
      <div className="flex items-center justify-between">
        <h2 className="text-sm font-medium">Text to speak</h2>
        <span
          className={`text-xs tabular-nums ${over ? "text-destructive" : "text-muted-foreground"}`}
        >
          {count.toLocaleString()} / {MAX_CHARS.toLocaleString()}
        </span>
      </div>
      <Textarea
        value={text}
        onChange={(e) => onChange(e.target.value)}
        disabled={disabled}
        placeholder="Type or paste text here…"
        className="min-h-44 resize-y text-base leading-relaxed"
        aria-label="Text to convert to speech"
      />
      <div className="flex gap-2">
        <Button
          variant="outline"
          size="sm"
          onClick={() => onChange("")}
          disabled={disabled || count === 0}
        >
          <Eraser className="mr-1 h-3.5 w-3.5" /> Clear
        </Button>
        <Button
          variant="outline"
          size="sm"
          onClick={() => onChange(SAMPLE_TEXT)}
          disabled={disabled}
        >
          <Sparkles className="mr-1 h-3.5 w-3.5" /> Try sample text
        </Button>
      </div>
      {over && (
        <p className="text-sm text-destructive">
          Text is too long — split it into smaller parts (limit{" "}
          {MAX_CHARS.toLocaleString()} characters).
        </p>
      )}
    </div>
  );
}
